theorem containerFamily_isContainerFamily {β : ℝ} {R q : ℕ}
    (h : Hypotheses G β R q) :
    IsContainerFamily G R q (containerFamily G q)

private theorem maxDegreeOrder_nodup_and_toFinset (A : Finset V) :
    (maxDegreeOrder G A).Nodup ∧
      (maxDegreeOrder G A).toFinset = A

theorem sdiff_fingerprint_subset_activeAfter {I : Finset V}
    (hI : G.IsIndepSet I) (q : ℕ) :
    I \ fingerprint G q I ⊆ activeAfter G q I

theorem card_encoding_snd {I : Finset V} {m q : ℕ}
    (hI : G.IsIndepSet I) (hIm : #I = m) (hqI : q ≤ #I) :
    #(encoding G q I).2 = m - q

theorem encoding_snd_subset_remainder {β : ℝ} {R q : ℕ}
    (h : Hypotheses G β R q) {I : Finset V}
    (hI : G.IsIndepSet I) (hqI : q ≤ #I) :
    (encoding G q I).2 ⊆ remainder G q (encoding G q I).1

private theorem log_choose_le_entropy {N q : ℕ} (hq : 0 < q) (hqN : q ≤ N) :
    Real.log (N.choose q : ℝ) ≤
      (q : ℝ) * (1 + Real.log (N : ℝ) - Real.log (q : ℝ))

private theorem entropyNumerator_mono {N x y : ℝ}
    (hx : 0 < x) (hxy : x ≤ y) (hyN : y ≤ N) :
    entropyNumerator N x ≤ entropyNumerator N y

private theorem eventually_one_add_log_sq_div_lt {δ : ℝ} (hδ : 0 < δ) :
    ∃ n₀ : ℕ, ∀ n : ℕ, n₀ ≤ n →
      (1 + Real.log (n : ℝ)) ^ 2 / (n : ℝ) < δ
